# ----------------------------------------------------------------------------
# time helpers
# ----------------------------------------------------------------------------


def utcnow():
    return datetime.now(timezone.utc)


def iso(dt=None):
    return (dt or utcnow()).isoformat(timespec="seconds").replace("+00:00", "Z")


def parse_iso(value):
    if not value:
        return None
    try:
        return datetime.fromisoformat(value.replace("Z", "+00:00"))
    except Exception:
        return None


# ----------------------------------------------------------------------------
# connections
# ----------------------------------------------------------------------------

_init_lock = threading.Lock()
_initialised = False


def get_conn():
    conn = sqlite3.connect(DB_PATH, timeout=15, isolation_level=None)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    conn.execute("PRAGMA busy_timeout = 15000")
    return conn


@contextmanager
def tx():
    conn = get_conn()
    try:
        conn.execute("BEGIN IMMEDIATE")
        yield conn
        conn.execute("COMMIT")
    except Exception:
        try:
            conn.execute("ROLLBACK")
        except Exception:
            pass
        raise
    finally:
        conn.close()


@contextmanager
def read():
    conn = get_conn()
    try:
        yield conn
    finally:
        conn.close()


# ----------------------------------------------------------------------------
# passwords / secrets
# ----------------------------------------------------------------------------

SCRYPT_N = 2 ** 14


def hash_secret(value: str) -> str:
    salt = os.urandom(16)
    dk = hashlib.scrypt(value.encode("utf-8"), salt=salt, n=SCRYPT_N, r=8, p=1, dklen=32)
    return "scrypt${}${}${}${}${}".format(
        SCRYPT_N, 8, 1,
        base64.b64encode(salt).decode(),
        base64.b64encode(dk).decode(),
    )


def verify_secret(value: str, encoded: str) -> bool:
    try:
        algo, n, r, p, salt_b64, dk_b64 = encoded.split("$")
        if algo != "scrypt":
            return False
        salt = base64.b64decode(salt_b64)
        expected = base64.b64decode(dk_b64)
        dk = hashlib.scrypt(value.encode("utf-8"), salt=salt, n=int(n), r=int(r), p=int(p), dklen=len(expected))
        return secrets.compare_digest(dk, expected)
    except Exception:
        return False


def hash_token(token: str) -> str:
    return hashlib.sha256(token.encode("utf-8")).hexdigest()


# ----------------------------------------------------------------------------
# settings
# ----------------------------------------------------------------------------


def get_setting(key, default=None):
    with read() as c:
        row = c.execute("SELECT value FROM settings WHERE key=?", (key,)).fetchone()
    if row:
        return row["value"]
    return DEFAULT_SETTINGS.get(key, default)


def get_settings():
    out = dict(DEFAULT_SETTINGS)
    with read() as c:
        for row in c.execute("SELECT key, value FROM settings"):
            out[row["key"]] = row["value"]
    return out


def set_setting(conn, key, value):
    conn.execute(
        "INSERT INTO settings(key, value) VALUES(?, ?) ON CONFLICT(key) DO UPDATE SET value=excluded.value",
        (key, str(value)),
    )


def setting_int(key, default=0):
    try:
        return int(get_setting(key, str(default)))
    except Exception:
        return default


# ----------------------------------------------------------------------------
# ledger (double-entry style, one row per wallet movement)
# ----------------------------------------------------------------------------


class InsufficientFunds(Exception):
    pass


TOPUP_KINDS = {"topup", "voucher", "voucher_redeem", "payment", "payment_credit",
               "admin_credit", "admin_adjust", "gift", "opening_balance", "agent_credit"}


def notify(conn, kind, title, body=None, ref=None, audience="admin"):
    conn.execute(
        "INSERT INTO notifications(audience, kind, title, body, ref, created_at) VALUES(?,?,?,?,?,?)",
        (audience, kind, title, body, ref, iso()),
    )


def mark_trial_use(conn, pin):
    """The free test pin's window starts the first time it is used."""
    try:
        hours = int(get_settings().get("trial_hours", 48))
    except Exception:
        hours = 48
    new_expiry = iso(utcnow() + timedelta(hours=max(1, hours)))
    conn.execute(
        "UPDATE trial_pins SET expires_at=? WHERE pin=? AND status='active' "
        "AND (expires_at IS NULL OR expires_at < ?)",
        (new_expiry, pin, new_expiry),
    )


def _after_move(conn, pin, amount_cents, kind):
    """Wallet rules that ride along with every ledger entry.

    * a free test pin's window starts the first time it spends anything
    * any top up pushes the pin's validity out by the configured months
    """
    amount_cents = int(amount_cents)
    now = utcnow()
    if amount_cents < 0:
        mark_trial_use(conn, pin)
    elif amount_cents > 0 and kind in TOPUP_KINDS:
        try:
            months = int(get_settings().get("pin_valid_months", 12))
        except Exception:
            months = 12
        if months > 0:
            until = iso(now + timedelta(days=30 * months))
            conn.execute(
                "UPDATE accounts SET valid_until=? WHERE pin=? AND COALESCE(is_master,0)=0 "
                "AND (valid_until IS NULL OR valid_until < ?)",
                (until, pin, until),
            )


def move(conn, pin, amount_cents, kind, *, counterparty=None, minutes=0, ref=None, note=None, allow_negative=False):
    """Apply a signed movement to a wallet and append the immutable ledger row."""
    row = conn.execute("SELECT balance_cents, status FROM accounts WHERE pin=?", (pin,)).fetchone()
    if not row:
        raise ValueError("unknown pin " + str(pin))
    balance = row["balance_cents"]
    new_balance = balance + int(amount_cents)
    if new_balance < 0 and not allow_negative:
        raise InsufficientFunds("insufficient funds")
    conn.execute("UPDATE accounts SET balance_cents=? WHERE pin=?", (new_balance, pin))
    conn.execute(
        "INSERT INTO ledger(ts, pin, counterparty, kind, amount_cents, minutes, balance_after, ref, note) "
        "VALUES(?,?,?,?,?,?,?,?,?)",
        (iso(), pin, counterparty, kind, int(amount_cents), int(minutes), new_balance, ref, note),
    )
    _after_move(conn, pin, amount_cents, kind)
    return new_balance


def audit(conn, actor, action, target=None, ip=None, meta=None):
    conn.execute(
        "INSERT INTO audit(ts, actor, action, target, ip, meta) VALUES(?,?,?,?,?,?)",
        (iso(), actor, action, target, ip, json.dumps(meta) if meta else None),
    )


def rate_hit(bucket):
    now = time.time()
    with tx() as c:
        c.execute("DELETE FROM rate_events WHERE ts < ?", (now - 86400,))
        c.execute("INSERT INTO rate_events(bucket, ts) VALUES(?, ?)", (bucket, now))
        return c.execute(
            "SELECT COUNT(*) AS n FROM rate_events WHERE bucket=? AND ts > ?", (bucket, now - 900)
        ).fetchone()["n"]


def rate_peek(bucket, window=900):
    with read() as c:
        return c.execute(
            "SELECT COUNT(*) AS n FROM rate_events WHERE bucket=? AND ts > ?", (bucket, time.time() - window)
        ).fetchone()["n"]


