def generate_pin(exists=None, prefix=""):
    """11 digit dialable pin. Never starts with 0."""
    for _ in range(200):
        body = "".join(secrets.choice("0123456789") for _ in range(11 - len(prefix) - 1))
        pin = f"{prefix}{secrets.choice('123456789')}{body}" if prefix else f"{secrets.choice('123456789')}{body}"
        pin = pin[:11]
        if len(pin) == 11 and (not exists or not exists(pin)):
            return pin
    raise RuntimeError("could not allocate pin")


def generate_password(length=10):
    alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789"
    return "".join(secrets.choice(alphabet) for _ in range(length))


def generate_voucher_code(prefix="PINLINK"):
    alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
    block = lambda n: "".join(secrets.choice(alphabet) for _ in range(n))
    return f"{prefix}-{block(4)}-{block(4)}-{block(4)}"


def pin_exists(pin):
    with read() as c:
        return c.execute("SELECT 1 FROM accounts WHERE pin=?", (pin,)).fetchone() is not None


