def _ensure_column(conn, table, column, decl):
    cols = {row[1] for row in conn.execute("PRAGMA table_info(%s)" % table).fetchall()}
    if column not in cols:
        conn.execute("ALTER TABLE %s ADD COLUMN %s %s" % (table, column, decl))


def _migrate(conn):
    """Additive only. Safe to run on every boot, keeps existing data."""
    _ensure_column(conn, "accounts", "avatar_url", "TEXT")
    _ensure_column(conn, "accounts", "valid_until", "TEXT")
    _ensure_column(conn, "accounts", "call_phone", "TEXT")


def init_db():
    global _initialised
    with _init_lock:
        if _initialised:
            return
        conn = get_conn()
        try:
            conn.execute("PRAGMA journal_mode=WAL")
            conn.execute("PRAGMA synchronous=NORMAL")
            conn.executescript(SCHEMA)
            _migrate(conn)
        finally:
            conn.close()
        if not _has_seed():
            seed_db()
        _initialised = True


def _has_seed():
    with read() as c:
        return c.execute("SELECT COUNT(*) AS n FROM accounts").fetchone()["n"] > 0


