import math
import threading
import time
from datetime import timedelta


# ----------------------------------------------------------------------------
# Billing engine
# ----------------------------------------------------------------------------
# Rules
#  * money is stored in integer cents, never floats
#  * every metered session gets a 45 second grace window (configurable)
#  * after grace, time is billed per started minute at the agent's rate
#  * balances are checked and debited inside a single IMMEDIATE transaction
#  * a session ends automatically the moment funds run out
# ----------------------------------------------------------------------------


class bl_BillingError(Exception):
    def __init__(self, message, status=400, code="billing_error", extra=None):
        super().__init__(message)
        self.message = message
        self.status = status
        self.code = code
        self.extra = extra or {}


def bl__account_row(conn, pin):
    return conn.execute(
        "SELECT pin, display_name, handle, role, status, balance_cents, avatar_seed, public_balance, cash_rate_cents, "
        "COALESCE(call_phone, '') AS call_phone FROM accounts WHERE pin=?", (pin,)
    ).fetchone()


def bl_public_account(row):
    if not row:
        return None
    return {
        "pin": row["pin"],
        "name": row["display_name"],
        "handle": row["handle"],
        "role": row["role"],
        "avatar_seed": row["avatar_seed"],
        "status": row["status"],
        "public_balance": bool(row["public_balance"]),
        "balance_cents": row["balance_cents"] if row["public_balance"] else None,
    }


def bl_active_discount(conn, caller_pin, agent_pin):
    row = conn.execute(
        "SELECT t.discount_pct FROM subscriptions s JOIN tiers t ON t.id = s.tier_id "
        "WHERE s.pin=? AND s.agent_pin=? AND s.status='active' AND s.ends_at > ? "
        "ORDER BY t.discount_pct DESC LIMIT 1",
        (caller_pin, agent_pin, iso()),
    ).fetchone()
    return int(row["discount_pct"]) if row else 0


def bl__service_for(conn, agent_pin, kind, service_id=None):
    if service_id:
        row = conn.execute("SELECT * FROM services WHERE id=? AND agent_pin=?", (service_id, agent_pin)).fetchone()
        if not row:
            raise bl_BillingError("service not found", 404, "service_not_found")
        return row
    row = conn.execute(
        "SELECT * FROM services WHERE agent_pin=? AND kind=? AND active=1 ORDER BY id LIMIT 1",
        (agent_pin, kind),
    ).fetchone()
    return row


def bl_start_session(caller_pin, to_pin, kind, service_id=None, show_id=None):
    settings = get_settings()
    grace = int(settings.get("grace_seconds", 45))
    with tx() as conn:
        caller = bl__account_row(conn, caller_pin)
        agent = bl__account_row(conn, to_pin)
        if not caller or not agent:
            raise bl_BillingError("pin not found", 404, "pin_not_found")
        if caller["status"] != "active":
            raise bl_BillingError("your pin is suspended", 403, "suspended")
        if agent["status"] != "active":
            raise bl_BillingError("that pin is not accepting sessions", 409, "agent_unavailable")
        if caller_pin == to_pin:
            raise bl_BillingError("you cannot dial your own pin", 400, "self_dial")

        mark_trial_use(conn, caller_pin)
        running = conn.execute(
            "SELECT id, last_seen FROM sessions WHERE caller_pin=? AND status='active' ORDER BY id DESC", (caller_pin,)
        ).fetchone()
        if running:
            # A session whose client stopped checking in (phone dialer opened, app
            # swiped away, battery died) must never lock the pin out of new calls.
            idle = (utcnow() - parse_iso(running["last_seen"])).total_seconds()
            if idle > 180:
                conn.execute(
                    "UPDATE sessions SET status='ended', ended_at=?, end_reason='connection_lost' WHERE id=?",
                    (iso(), running["id"]),
                )
                audit(conn, caller_pin, "session.end", to_pin, None,
                      {"session_id": running["id"], "reason": "connection_lost_auto"})
            else:
                raise bl_BillingError("you already have a live session", 409, "session_active",
                                   {"session_id": running["id"]})

        show = None
        if show_id:
            show = conn.execute("SELECT * FROM live_shows WHERE id=?", (show_id,)).fetchone()
            if not show:
                raise bl_BillingError("show not found", 404, "show_not_found")
            if show["agent_pin"] != to_pin:
                raise bl_BillingError("show does not belong to that pin", 400, "show_mismatch")
            if show["ppv_cents"] > 0:
                ticket = conn.execute(
                    "SELECT 1 FROM tickets WHERE show_id=? AND buyer_pin=?", (show_id, caller_pin)
                ).fetchone()
                if not ticket:
                    raise bl_BillingError("ticket required for this show", 402, "ticket_required",
                                       {"ppv_cents": show["ppv_cents"]})
            rate = int(show["rate_cents_per_min"])
        else:
            svc = bl__service_for(conn, to_pin, kind, service_id)
            if not svc and kind == "tel":
                # Cellular hand-off bills the same minute rate as the voice line.
                svc = bl__service_for(conn, to_pin, "voice", None)
            if not svc:
                raise bl_BillingError(f"this pin does not offer {kind} right now", 404, "service_unavailable")
            if kind == "tel" and not (agent["call_phone"] or "").strip():
                raise bl_BillingError("this creator has not added a phone number yet", 409, "no_phone")
            rate = int(svc["rate_cents_per_min"])
            service_id = svc["id"]
            if kind == "text" and rate == 0:
                raise bl_BillingError("this pin bills texts per message, not per minute", 400, "per_message_service")

        discount = bl_active_discount(conn, caller_pin, to_pin)
        first_minute = bl__round_cents(rate, discount)
        if first_minute > 0 and caller["balance_cents"] < first_minute:
            raise bl_BillingError("not enough credit for the first minute", 402, "insufficient_funds",
                               {"needed_cents": first_minute, "balance_cents": caller["balance_cents"]})

        now = iso()
        cur = conn.execute(
            "INSERT INTO sessions(kind, caller_pin, agent_pin, service_id, show_id, rate_cents, discount_pct, "
            "grace_seconds, started_at, last_seen, status) VALUES(?,?,?,?,?,?,?,?,?,?,'active')",
            (kind, caller_pin, to_pin, service_id, show_id, rate, discount, grace, now, now),
        )
        sid = cur.lastrowid
        audit(conn, caller_pin, "session.start", to_pin, None,
              {"session_id": sid, "kind": kind, "rate_cents": rate, "discount_pct": discount})
    return bl_get_session(sid)


def bl__round_cents(rate_cents, discount_pct):
    return int(math.ceil(rate_cents * (100 - int(discount_pct)) / 100.0 - 1e-9))


def bl__due(minutes, rate_cents, discount_pct):
    if minutes <= 0:
        return 0
    return int(math.ceil(minutes * rate_cents * (100 - int(discount_pct)) / 100.0 - 1e-9))


def bl_settle(session_id, *, heartbeat=True, force_end=False, reason=None):
    """Recompute the session from server time and move any newly accrued money."""
    fee_pct = setting_int("platform_fee_pct", 0)
    with tx() as conn:
        s = conn.execute("SELECT * FROM sessions WHERE id=?", (session_id,)).fetchone()
        if not s:
            raise bl_BillingError("session not found", 404, "session_not_found")
        if s["status"] != "active":
            return bl__session_view(conn, s, ended=True)

        now = utcnow()
        started = parse_iso(s["started_at"])
        last_seen = parse_iso(s["last_seen"])
        elapsed = max(0.0, (now - started).total_seconds())
        stale = (now - last_seen).total_seconds() > 30
        if stale:
            # never bill time after the client stopped checking in (+30s tolerance)
            elapsed = min(elapsed, max(0.0, (last_seen - started).total_seconds()) + 30)

        billable = max(0, elapsed - s["grace_seconds"])
        minutes = int(math.ceil(billable / 60.0 - 1e-9)) if billable > 0 else 0
        due = bl__due(minutes, s["rate_cents"], s["discount_pct"])
        delta = max(0, due - s["amount_cents"])

        end_reason = reason
        if delta > 0:
            balance = conn.execute("SELECT balance_cents FROM accounts WHERE pin=?", (s["caller_pin"],)).fetchone()["balance_cents"]
            pay = min(delta, balance)
            if pay > 0:
                move(conn, s["caller_pin"], -pay, "session_charge", counterparty=s["agent_pin"],
                     minutes=minutes, ref=f"session:{session_id}", note=f"{s['kind']} session")
                fee = int(math.floor(pay * fee_pct / 100.0)) if fee_pct else 0
                agent_share = pay - fee
                if agent_share > 0:
                    move(conn, s["agent_pin"], agent_share, "session_earning", counterparty=s["caller_pin"],
                         minutes=minutes, ref=f"session:{session_id}", note=f"{s['kind']} session revenue")
                if fee > 0:
                    master = conn.execute("SELECT pin FROM accounts WHERE is_master=1 LIMIT 1").fetchone()
                    if master:
                        move(conn, master["pin"], fee, "platform_fee", counterparty=s["agent_pin"],
                             ref=f"session:{session_id}", note="platform fee")
                conn.execute("UPDATE sessions SET amount_cents = amount_cents + ?, billed_minutes = ? WHERE id=?",
                             (pay, minutes, session_id))
            if pay < delta and not end_reason:
                end_reason = "funds_depleted"
                force_end = True

        if force_end or (stale and not heartbeat):
            end_reason = end_reason or ("client_closed" if not stale else "connection_lost")
            conn.execute(
                "UPDATE sessions SET status='ended', ended_at=?, last_seen=?, end_reason=? WHERE id=?",
                (iso(), iso(now), end_reason, session_id),
            )
            audit(conn, s["caller_pin"], "session.end", s["agent_pin"], None,
                  {"session_id": session_id, "reason": end_reason, "amount_cents": s["amount_cents"]})
        else:
            conn.execute("UPDATE sessions SET last_seen=? WHERE id=?", (iso(now), session_id))
        s = conn.execute("SELECT * FROM sessions WHERE id=?", (session_id,)).fetchone()
        return bl__session_view(conn, s, ended=s["status"] != "active")


def bl__session_view(conn, s, ended=False):
    now = utcnow()
    started = parse_iso(s["started_at"])
    last_seen = parse_iso(s["last_seen"])
    elapsed = max(0.0, (now - started).total_seconds())
    if s["status"] == "ended" and s["ended_at"]:
        elapsed = max(0.0, (parse_iso(s["ended_at"]) - started).total_seconds())
    else:
        elapsed = min(elapsed, (now - last_seen).total_seconds() + 30) if (now - last_seen).total_seconds() > 30 else elapsed
    billable = max(0, elapsed - s["grace_seconds"])
    minutes = int(math.ceil(billable / 60.0 - 1e-9)) if billable > 0 else 0
    agent = bl__account_row(conn, s["agent_pin"])
    caller = bl__account_row(conn, s["caller_pin"])
    balance = caller["balance_cents"] if caller else 0
    per_min = bl__round_cents(s["rate_cents"], s["discount_pct"])
    return {
        "id": s["id"],
        "kind": s["kind"],
        "status": s["status"],
        "started_at": s["started_at"],
        "grace_seconds": s["grace_seconds"],
        "rate_cents": s["rate_cents"],
        "per_minute_cents": per_min,
        "discount_pct": s["discount_pct"],
        "elapsed_seconds": int(elapsed),
        "billable_seconds": int(billable),
        "billed_minutes": minutes,
        "amount_cents": s["amount_cents"],
        "balance_cents": balance,
        "remaining_minutes": int(balance // per_min) if per_min else None,
        "end_reason": s["end_reason"],
        "agent": bl_public_account(agent),
        "agent_name": agent["display_name"] if agent else "",
        "agent_phone": (agent["call_phone"] or None) if agent else None,
        "caller": bl_public_account(caller),
    }


def bl_get_session(session_id, caller_pin=None):
    with read() as conn:
        s = conn.execute("SELECT * FROM sessions WHERE id=?", (session_id,)).fetchone()
        if not s:
            raise bl_BillingError("session not found", 404, "session_not_found")
        if caller_pin and s["caller_pin"] != caller_pin:
            raise bl_BillingError("not your session", 403, "forbidden")
        return bl__session_view(conn, s)


def bl_active_session(caller_pin):
    with read() as conn:
        s = conn.execute("SELECT * FROM sessions WHERE caller_pin=? AND status='active' ORDER BY id DESC LIMIT 1",
                         (caller_pin,)).fetchone()
        return bl__session_view(conn, s) if s else None


# ----------------------------------------------------------------------------
# wallet operations
# ----------------------------------------------------------------------------


def bl_redeem_voucher(pin, code):
    code = (code or "").strip().upper()
    with tx() as conn:
        v = conn.execute("SELECT * FROM vouchers WHERE code=?", (code,)).fetchone()
        if not v:
            raise bl_BillingError("voucher not found", 404, "voucher_not_found")
        if v["status"] != "active":
            raise bl_BillingError("voucher already used", 409, "voucher_used")
        if v["expires_at"] and parse_iso(v["expires_at"]) < utcnow():
            raise bl_BillingError("voucher expired", 410, "voucher_expired")
        amount = int(v["value_cents"])
        minutes = int(v["minutes"])
        if minutes and not amount:
            amount = minutes * setting_int("minute_value_cents", 1)
        conn.execute("UPDATE vouchers SET status='redeemed', redeemed_by=?, redeemed_at=? WHERE code=?", (pin, iso(), code))
        new_balance = move(conn, pin, amount, "voucher", minutes=minutes, ref=code, note="voucher top-up")
        audit(conn, pin, "voucher.redeem", code, None, {"amount_cents": amount})
    return {"amount_cents": amount, "minutes": minutes, "balance_cents": new_balance, "code": code}


def bl_transfer(pin, to_pin, amount_cents, note=None, idempotency_key=None):
    amount_cents = int(amount_cents)
    if amount_cents < 1:
        raise bl_BillingError("amount must be at least 1 cent", 400, "invalid_amount")
    if pin == to_pin:
        raise bl_BillingError("cannot bl_transfer to the same pin", 400, "self_transfer")
    with tx() as conn:
        if idempotency_key:
            existing = conn.execute(
                "SELECT * FROM ledger WHERE pin=? AND ref=? AND kind='transfer_out'", (pin, idempotency_key)
            ).fetchone()
            if existing:
                return {"duplicate": True, "amount_cents": abs(existing["amount_cents"]),
                        "balance_cents": existing["balance_after"]}
        target = bl__account_row(conn, to_pin)
        if not target:
            raise bl_BillingError("destination pin not found", 404, "pin_not_found")
        if target["status"] != "active":
            raise bl_BillingError("destination pin is suspended", 409, "pin_suspended")
        minute_value = setting_int("minute_value_cents", 1)
        minutes = amount_cents // minute_value if minute_value else 0
        new_balance = move(conn, pin, -amount_cents, "transfer_out", counterparty=to_pin, minutes=minutes,
                           ref=idempotency_key, note=note or "credit bl_transfer")
        move(conn, to_pin, amount_cents, "transfer_in", counterparty=pin, minutes=minutes,
             ref=idempotency_key, note=note or "credit bl_transfer")
        audit(conn, pin, "wallet.bl_transfer", to_pin, None, {"amount_cents": amount_cents})
    return {"amount_cents": amount_cents, "balance_cents": new_balance, "minutes": minutes}


def bl_gift(from_pin, to_pin, minutes, note=None, context_kind=None, context_id=None):
    minutes = int(minutes)
    if minutes < 1:
        raise bl_BillingError("bl_gift must be at least 1 minute", 400, "invalid_gift")
    minute_value = setting_int("minute_value_cents", 1)
    amount = minutes * minute_value
    with tx() as conn:
        target = bl__account_row(conn, to_pin)
        if not target:
            raise bl_BillingError("pin not found", 404, "pin_not_found")
        if from_pin == to_pin:
            raise bl_BillingError("you cannot bl_gift yourself", 400, "self_gift")
        new_balance = move(conn, from_pin, -amount, "gift_out", counterparty=to_pin, minutes=minutes,
                           note=note or "bl_gift")
        move(conn, to_pin, amount, "gift_in", counterparty=from_pin, minutes=minutes, note=note or "bl_gift")
        conn.execute(
            "INSERT INTO gifts(from_pin, to_pin, minutes, amount_cents, context_kind, context_id, note, created_at) "
            "VALUES(?,?,?,?,?,?,?,?)",
            (from_pin, to_pin, minutes, amount, context_kind, context_id, note, iso()),
        )
        audit(conn, from_pin, "wallet.bl_gift", to_pin, None, {"minutes": minutes, "amount_cents": amount})
    return {"minutes": minutes, "amount_cents": amount, "balance_cents": new_balance}


def bl_send_message(from_pin, to_pin, body, session_id=None):
    body = (body or "").strip()
    if not body:
        raise bl_BillingError("message is empty", 400, "empty_message")
    if len(body) > 2000:
        raise bl_BillingError("message too long", 400, "message_too_long")
    a, b = sorted([from_pin, to_pin])
    with tx() as conn:
        target = bl__account_row(conn, to_pin)
        if not target:
            raise bl_BillingError("pin not found", 404, "pin_not_found")
        if from_pin == to_pin:
            raise bl_BillingError("cannot text yourself", 400, "self_message")
        conn.execute(
            "INSERT INTO threads(a_pin, b_pin, created_at) VALUES(?,?,?) "
            "ON CONFLICT(a_pin, b_pin) DO NOTHING", (a, b, iso())
        )
        thread = conn.execute("SELECT * FROM threads WHERE a_pin=? AND b_pin=?", (a, b)).fetchone()
        price = 0
        if from_pin != to_pin:
            svc = conn.execute(
                "SELECT per_use_cents FROM services WHERE agent_pin=? AND kind='text' AND active=1 ORDER BY id LIMIT 1",
                (to_pin,),
            ).fetchone()
            if svc:
                price = int(svc["per_use_cents"] or 0)
        if price > 0:
            move(conn, from_pin, -price, "message_charge", counterparty=to_pin, ref=f"thread:{thread['id']}",
                 note="per-message text")
            move(conn, to_pin, price, "message_earning", counterparty=from_pin, ref=f"thread:{thread['id']}",
                 note="per-message text")
        cur = conn.execute(
            "INSERT INTO messages(thread_id, from_pin, to_pin, body, ts, charged_cents, session_id) VALUES(?,?,?,?,?,?,?)",
            (thread["id"], from_pin, to_pin, body, iso(), price, session_id),
        )
        conn.execute("UPDATE threads SET last_message_at=? WHERE id=?", (iso(), thread["id"]))
    return {"id": cur.lastrowid, "thread_id": thread["id"], "charged_cents": price}


def bl_buy_ticket(buyer_pin, show_id):
    with tx() as conn:
        show = conn.execute("SELECT * FROM live_shows WHERE id=?", (show_id,)).fetchone()
        if not show:
            raise bl_BillingError("show not found", 404, "show_not_found")
        existing = conn.execute(
            "SELECT * FROM tickets WHERE show_id=? AND buyer_pin=?", (show_id, buyer_pin)
        ).fetchone()
        if existing:
            return {"ticket_id": existing["id"], "price_cents": existing["price_cents"], "already": True}
        price = int(show["ppv_cents"])
        if price > 0:
            move(conn, buyer_pin, -price, "ticket_purchase", counterparty=show["agent_pin"],
                 ref=f"show:{show_id}", note=show["title"])
            move(conn, show["agent_pin"], price, "ticket_earning", counterparty=buyer_pin,
                 ref=f"show:{show_id}", note=show["title"])
        cur = conn.execute(
            "INSERT INTO tickets(show_id, buyer_pin, price_cents, created_at) VALUES(?,?,?,?)",
            (show_id, buyer_pin, price, iso()),
        )
        audit(conn, buyer_pin, "show.ticket", str(show_id), None, {"price_cents": price})
    return {"ticket_id": cur.lastrowid, "price_cents": price, "already": False}


def bl_subscribe(pin, tier_id):
    with tx() as conn:
        tier = conn.execute("SELECT * FROM tiers WHERE id=? AND active=1", (tier_id,)).fetchone()
        if not tier:
            raise bl_BillingError("tier not found", 404, "tier_not_found")
        if pin == tier["agent_pin"]:
            raise bl_BillingError("cannot bl_subscribe to yourself", 400, "self_subscribe")
        price = int(tier["price_cents"])
        move(conn, pin, -price, "subscription", counterparty=tier["agent_pin"], ref=f"tier:{tier_id}",
             note=f"{tier['name']} monthly tier")
        move(conn, tier["agent_pin"], price, "subscription_earning", counterparty=pin, ref=f"tier:{tier_id}",
             note=f"{tier['name']} monthly tier")
        included = int(tier["included_minutes"] or 0)
        if included > 0:
            value = included * setting_int("minute_value_cents", 1)
            move(conn, pin, value, "tier_minutes", counterparty=tier["agent_pin"], minutes=included,
                 ref=f"tier:{tier_id}", note=f"{included} included minutes")
            # included minutes are promotional credit, not cashable revenue
            move(conn, tier["agent_pin"], -value, "tier_minutes_liability", counterparty=pin, minutes=included,
                 ref=f"tier:{tier_id}", note="included minutes grant")
        ends = utcnow() + timedelta(days=int(tier["period_days"] or 30))
        cur = conn.execute(
            "INSERT INTO subscriptions(pin, tier_id, agent_pin, price_cents, started_at, ends_at, status, auto_renew) "
            "VALUES(?,?,?,?,?,?,'active',1)",
            (pin, tier_id, tier["agent_pin"], price, iso(), iso(ends)),
        )
        audit(conn, pin, "tier.bl_subscribe", str(tier_id), None, {"price_cents": price})
    return {"subscription_id": cur.lastrowid, "ends_at": iso(ends), "price_cents": price}


def bl_cashable_cents(conn, pin):
    row = conn.execute(
        "SELECT COALESCE(SUM(CASE WHEN kind IN ('session_earning','gift_in','message_earning','ticket_earning','subscription_earning') THEN amount_cents ELSE 0 END),0) AS earned, "
        "COALESCE(SUM(CASE WHEN kind='payout' THEN -amount_cents ELSE 0 END),0) AS paid "
        "FROM ledger WHERE pin=?", (pin,),
    ).fetchone()
    return max(0, int(row["earned"]) - int(row["paid"]))


def bl_run_payouts(admin_actor, period_date=None, ip=None):
    period_date = period_date or utcnow().date().isoformat()
    minute_value = setting_int("minute_value_cents", 1)
    created = []
    with tx() as conn:
        agents = conn.execute(
            "SELECT pin, balance_cents, display_name FROM accounts WHERE role='agent' AND status='active' AND is_master=0"
        ).fetchall()
        for a in agents:
            cashable = bl_cashable_cents(conn, a["pin"])
            if cashable <= 0:
                continue
            net = min(cashable, int(a["balance_cents"]))
            if net <= 0:
                continue
            already = conn.execute(
                "SELECT 1 FROM payouts WHERE agent_pin=? AND period_date=? AND status IN ('pending','paid')",
                (a["pin"], period_date),
            ).fetchone()
            if already:
                continue
            minutes = net // minute_value if minute_value else 0
            cur = conn.execute(
                "INSERT INTO payouts(agent_pin, period_date, gross_cents, fee_cents, net_cents, minutes, status, created_at, note) "
                "VALUES(?,?,?,?,?,?,'pending',?,?)",
                (a["pin"], period_date, cashable, 0, net, minutes, iso(), "daily settlement"),
            )
            move(conn, a["pin"], -net, "payout", counterparty="house", minutes=minutes,
                 ref=f"payout:{cur.lastrowid}", note=f"daily payout {period_date}")
            created.append({"payout_id": cur.lastrowid, "agent_pin": a["pin"], "name": a["display_name"],
                            "net_cents": net, "minutes": minutes})
        audit(conn, admin_actor, "payout.run", period_date, ip, {"count": len(created)})
    return {"period_date": period_date, "payouts": created, "total_cents": sum(p["net_cents"] for p in created)}


def bl_mark_payout(payout_id, actor, status="paid", ip=None, note=None):
    with tx() as conn:
        p = conn.execute("SELECT * FROM payouts WHERE id=?", (payout_id,)).fetchone()
        if not p:
            raise bl_BillingError("payout not found", 404, "payout_not_found")
        if p["status"] != "pending":
            raise bl_BillingError("payout already settled", 409, "payout_settled")
        if status == "void":
            move(conn, p["agent_pin"], p["net_cents"], "payout_reversal", counterparty="house",
                 ref=f"payout:{payout_id}", note="payout voided")
        conn.execute(
            "UPDATE payouts SET status=?, paid_at=?, paid_by=?, note=COALESCE(?, note) WHERE id=?",
            (status, iso() if status == "paid" else None, actor, note, payout_id),
        )
        audit(conn, actor, f"payout.{status}", str(payout_id), ip, {"net_cents": p["net_cents"]})
    return {"ok": True}


# ----------------------------------------------------------------------------
# background sweeper: never leave a call billing forever if a browser dies
# ----------------------------------------------------------------------------


def bl__sweeper():
    while True:
        try:
            with read() as conn:
                stale = conn.execute(
                    "SELECT id FROM sessions WHERE status='active' AND last_seen < ?",
                    (iso(utcnow() - timedelta(seconds=45)),),
                ).fetchall()
            for row in stale:
                try:
                    bl_settle(row["id"], heartbeat=False, force_end=True, reason="connection_lost")
                except Exception as exc:  # pragma: no cover
                    print("[pinlink] sweep error", exc)
        except Exception as exc:  # pragma: no cover
            print("[pinlink] sweeper error", exc)
        time.sleep(20)


def bl_start_sweeper():
    t = threading.Thread(target=bl__sweeper, name="pinlink-sweeper", daemon=True)
    t.start()
    return t


import json
import secrets
import string
from datetime import timedelta


# ----------------------------------------------------------------------------
# Payments
# ----------------------------------------------------------------------------
# Methods: an 11 digit pin (treated exactly like a debit / credit card),
# Cash App, PayPal and cash. Every method listed here is live.
#
# Money is still integer cents and every state change writes ledger rows, so a
# top-up is never a client-side illusion.
# ----------------------------------------------------------------------------

pm_INSUFFICIENT_MESSAGE = (
    "Insufficient funds \u2014 please top up or contact customer service."
)

pm_METHODS = [
    {
        "id": "pin",
        "name": "11-digit PIN",
        "short": "Pin",
        "blurb": "Pay from any funded PinLink pin. Works like a debit card.",
        "tagline": "Instant \u00b7 no fees",
        "enabled_key": "pay_pin_enabled",
        "kind": "instant",
    },
    {
        "id": "cashapp",
        "name": "Cash App",
        "short": "Cash App",
        "blurb": "Send the amount to our Cash App tag, then confirm here.",
        "tagline": "Confirmed by support",
        "enabled_key": "pay_cashapp_enabled",
        "kind": "manual",
    },
    {
        "id": "paypal",
        "name": "PayPal",
        "short": "PayPal",
        "blurb": "Pay with a PayPal balance, bank or linked card.",
        "tagline": "Confirmed by support",
        "enabled_key": "pay_paypal_enabled",
        "kind": "manual",
    },
    {
        "id": "cash",
        "name": "Cash",
        "short": "Cash",
        "blurb": "Pay an authorized agent in person and enter your receipt code.",
        "tagline": "Agent network",
        "enabled_key": "pay_cash_enabled",
        "kind": "manual",
    },
]

pm_MIN_CENTS = 100
pm_MAX_CENTS = 1_000_000  # $10,000.00 per top-up


class pm_PaymentError(Exception):
    def __init__(self, message, status=400, code="payment_error", extra=None):
        super().__init__(message)
        self.message = message
        self.status = status
        self.code = code
        self.extra = extra or {}


def pm__flag(settings, key, default="1"):
    return str(settings.get(key, default)) == "1"


def pm__limits(settings):
    try:
        lo = int(settings.get("pay_min_cents", pm_MIN_CENTS))
    except (TypeError, ValueError):
        lo = pm_MIN_CENTS
    try:
        hi = int(settings.get("pay_max_cents", pm_MAX_CENTS))
    except (TypeError, ValueError):
        hi = pm_MAX_CENTS
    return max(100, lo), max(lo, hi)


def pm_public_config(settings=None):
    s = settings or get_settings()
    lo, hi = pm__limits(s)
    tag = (s.get("pay_cashapp_tag") or "$Sellous1").strip()
    if tag and not tag.startswith("$"):
        tag = "$" + tag
    link = (s.get("pay_cashapp_link") or "").strip() or ("https://cash.app/" + tag)
    paypal = (s.get("pay_paypal_handle") or "").strip()
    paypal_link = (s.get("pay_paypal_link") or "").strip() or (
        "https://www.paypal.com/paypalme/" + paypal if paypal else ""
    )
    return {
        "currency": s.get("currency", "USD"),
        "min_cents": lo,
        "max_cents": hi,
        "cashapp_tag": tag,
        "cashapp_link": link,
        "paypal_handle": paypal,
        "paypal_link": paypal_link,
        "cash_instructions": s.get("pay_cash_instructions") or (
            "Pay cash to an authorized PinLink agent or reseller. "
            "Ask for a cash receipt code and enter it on this screen."
        ),
        "support": s.get("support_contact") or "support@pinlink.app",
    }


def pm_methods(settings=None):
    s = settings or get_settings()
    out = []
    for m in pm_METHODS:
        enabled = pm__flag(s, m["enabled_key"], "1")
        item = dict(m)
        item.pop("enabled_key", None)
        item["enabled"] = bool(enabled)
        out.append(item)
    return out


def pm__validate_amount(amount_cents, settings):
    try:
        amount_cents = int(amount_cents)
    except (TypeError, ValueError):
        raise pm_PaymentError("Enter a valid amount", 400, "invalid_amount")
    lo, hi = pm__limits(settings)
    if amount_cents < lo:
        raise pm_PaymentError(f"Minimum top-up is ${lo / 100:,.2f}", 400, "amount_too_small")
    if amount_cents > hi:
        raise pm_PaymentError(f"Maximum top-up is ${hi / 100:,.2f} per transaction", 400, "amount_too_large")
    return amount_cents


def pm__reference():
    alphabet = string.ascii_uppercase + string.digits
    body = "".join(secrets.choice(alphabet) for _ in range(6))
    return "PL-" + body


def pm__payment_dict(row, names=None):
    d = dict(row)
    if names is not None:
        d["pin_name"] = names.get(d["pin"], d["pin"])
        d["tendered_name"] = names.get(d.get("tendered_pin") or "", None)
    d["minutes"] = 0
    try:
        d["meta"] = json.loads(d["meta"]) if d.get("meta") else {}
    except (TypeError, ValueError):
        d["meta"] = {}
    return d


def pm__insert(conn, *, pin, method, amount_cents, status, tendered_pin=None,
            code=None, reference=None, note=None, instructions=None, meta=None,
            idempotency_key=None, total_cents=None, fee_cents=0):
    pid = "pay_" + secrets.token_hex(8)
    now = iso()
    conn.execute(
        "INSERT INTO payments(id, code, pin, method, amount_cents, fee_cents, total_cents, status, "
        "tendered_pin, reference, note, instructions, meta, idempotency_key, created_at, updated_at) "
        "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
        (pid, code, pin, method, int(amount_cents), int(fee_cents),
         int(total_cents if total_cents is not None else amount_cents), status,
         tendered_pin, reference, note, instructions,
         json.dumps(meta) if meta else None, idempotency_key, now, now),
    )
    return pid


def pm__instructions(settings, method):
    cfg = pm_public_config(settings)
    if method == "cashapp":
        return {
            "headline": f"Send {tag}" if (tag := cfg["cashapp_tag"]).startswith("$") else f"Send ${tag}",
            "payee": cfg["cashapp_tag"],
            "link": cfg["cashapp_link"],
            "steps": [
                f"Open Cash App and send the exact amount to {cfg['cashapp_tag']}.",
                "Put the reference code in the payment note.",
                "Come back here and tap \u201cI sent it\u201d so support can verify.",
            ],
            "note": "Cash App payments are verified by a human, usually within one business day.",
        }
    if method == "paypal":
        return {
            "headline": "Pay with PayPal",
            "payee": cfg["paypal_handle"] or "support@pinlink.app",
            "link": cfg["paypal_link"],
            "steps": [
                "Open the PayPal link and send the exact amount as goods and services.",
                "Include the reference code in the PayPal note.",
                "Tap \u201cI sent it\u201d here once the payment is complete.",
            ],
            "note": "PayPal payments are verified by support before credit lands.",
        }
    return {
        "headline": "Pay cash to an agent",
        "payee": "Authorized PinLink agent",
        "link": "",
        "steps": [
            cfg["cash_instructions"],
            "Enter the cash receipt code your agent gives you.",
            "Support confirms it and your balance updates.",
        ],
        "note": "Never hand cash to someone who cannot show a PinLink agent code.",
    }


def pm_create_manual(pin, method, amount_cents, note=None):
    settings = get_settings()
    settings_methods = {m["id"]: m for m in pm_methods(settings)}
    m = settings_methods.get(method)
    if not m:
        raise pm_PaymentError("Unknown payment method", 400, "unknown_method")
    if method == "pin":
        raise pm_PaymentError("Use the pin checkout for pin payments", 400, "wrong_endpoint")
    if not m["enabled"]:
        raise pm_PaymentError(f"{m['name']} is temporarily unavailable", 503, "method_disabled")

    amount_cents = pm__validate_amount(amount_cents, settings)
    with tx() as conn:
        ref = pm__reference()
        for _ in range(5):
            if not conn.execute("SELECT 1 FROM payments WHERE code=?", (ref,)).fetchone():
                break
            ref = pm__reference()
        info = pm__instructions(settings, method)
        meta = {"payee": info.get("payee"), "link": info.get("link"), "steps": info.get("steps")}
        pid = pm__insert(conn, pin=pin, method=method, amount_cents=amount_cents,
                      status="pending", code=ref, note=note, meta=meta,
                      instructions=json.dumps(info))
        row = conn.execute("SELECT * FROM payments WHERE id=?", (pid,)).fetchone()
    out = pm__payment_dict(row)
    out["instructions"] = info
    return out


def pm_create_pin_charge(buyer_pin, tendered_pin, password, amount_cents, note=None,
                      idempotency_key=None):
    """Debit the tendered pin (like a card) and credit the buyer's wallet."""
    settings = get_settings()
    if not pm__flag(settings, "pay_pin_enabled", "1"):
        raise pm_PaymentError("Pin payments are temporarily unavailable", 503, "method_disabled")
    amount_cents = pm__validate_amount(amount_cents, settings)
    minute_value = int(settings.get("minute_value_cents", 1) or 1)

    with tx() as conn:
        if idempotency_key:
            prev = conn.execute(
                "SELECT * FROM payments WHERE idempotency_key=? AND pin=?",
                (idempotency_key, buyer_pin),
            ).fetchone()
            if prev:
                return pm__payment_dict(prev)

        tendered = conn.execute("SELECT * FROM accounts WHERE pin=?", (tendered_pin,)).fetchone()
        if not tendered:
            raise pm_PaymentError("No PinLink account uses that pin", 404, "pin_not_found")
        if tendered["status"] != "active":
            raise pm_PaymentError("That pin is not active", 403, "pin_inactive")
        if tendered_pin == buyer_pin:
            raise pm_PaymentError("Choose a different funding pin \u2014 this is the wallet you are topping up",
                               400, "same_pin")
        if not verify_secret(password or "", tendered["password_hash"]):
            raise pm_PaymentError("That pin password is incorrect", 401, "bad_pin_password")

        balance = int(tendered["balance_cents"])
        if balance < amount_cents:
            short = amount_cents - balance
            raise pm_PaymentError(
                pm_INSUFFICIENT_MESSAGE, 402, "insufficient_funds",
                {
                    "speak": pm_INSUFFICIENT_MESSAGE,
                    "balance_cents": balance,
                    "required_cents": amount_cents,
                    "shortfall_cents": short,
                    "tendered_pin": tendered_pin,
                },
            )

        ref = pm__reference()
        meta = {"tendered_pin": tendered_pin, "minutes": amount_cents // minute_value if minute_value else 0}
        pid = pm__insert(
            conn, pin=buyer_pin, method="pin", amount_cents=amount_cents, status="paid",
            tendered_pin=tendered_pin, code=ref, note=note, meta=meta,
            idempotency_key=idempotency_key,
        )
        move(conn, tendered_pin, -amount_cents, "pin_purchase", counterparty=buyer_pin,
             ref=pid, note=f"Card-style purchase {ref}")
        move(conn, buyer_pin, amount_cents, "topup", counterparty=tendered_pin,
             ref=pid, note=f"Top-up paid by pin {ref}")
        audit(conn, buyer_pin, "payment.pin", pid, None,
              {"amount_cents": amount_cents, "tendered_pin": tendered_pin})
        row = conn.execute("SELECT * FROM payments WHERE id=?", (pid,)).fetchone()

    out = pm__payment_dict(row)
    out["minutes"] = amount_cents // minute_value if minute_value else 0
    out["new_balance_cents"] = balance - amount_cents
    return out


def pm_attach_reference(payment_id, pin, reference):
    reference = (reference or "").strip()[:80]
    if not reference:
        raise pm_PaymentError("Enter the payment reference or receipt code", 400, "reference_required")
    with tx() as conn:
        row = conn.execute("SELECT * FROM payments WHERE id=? AND pin=?", (payment_id, pin)).fetchone()
        if not row:
            raise pm_PaymentError("Payment not found", 404, "payment_not_found")
        if row["status"] != "pending":
            raise pm_PaymentError(f"This payment is already {row['status']}", 409, "payment_closed")
        conn.execute(
            "UPDATE payments SET reference=?, updated_at=? WHERE id=?",
            (reference, iso(), payment_id),
        )
        audit(conn, pin, "payment.claim", payment_id, None, {"reference": reference})
        notify(conn, "payment.claim", "Payment claim needs review",
               "Pin %s says they sent %s by %s. Transaction ID: %s" % (
                   pin, "$%.2f" % ((row["amount_cents"] or 0) / 100.0), row["method"], reference),
               ref=payment_id)
        out = conn.execute("SELECT * FROM payments WHERE id=?", (payment_id,)).fetchone()
    return pm__payment_dict(out)


def pm_user_payments(pin, limit=25):
    with read() as conn:
        rows = conn.execute(
            "SELECT * FROM payments WHERE pin=? ORDER BY created_at DESC LIMIT ?",
            (pin, max(1, min(100, limit))),
        ).fetchall()
    return [pm__payment_dict(r) for r in rows]


def pm_get_payment(payment_id, pin=None):
    with read() as conn:
        if pin:
            row = conn.execute("SELECT * FROM payments WHERE id=? AND pin=?", (payment_id, pin)).fetchone()
        else:
            row = conn.execute("SELECT * FROM payments WHERE id=?", (payment_id,)).fetchone()
    if not row:
        raise pm_PaymentError("Payment not found", 404, "payment_not_found")
    out = pm__payment_dict(row)
    try:
        out["instructions"] = json.loads(row["instructions"]) if row["instructions"] else None
    except (TypeError, ValueError):
        out["instructions"] = None
    return out


def pm_admin_list(status=None, limit=200):
    sql = ("SELECT p.*, a.display_name AS pin_name FROM payments p "
           "LEFT JOIN accounts a ON a.pin = p.pin WHERE 1=1")
    args = []
    if status:
        sql += " AND p.status=?"
        args.append(status)
    sql += " ORDER BY p.created_at DESC LIMIT ?"
    args.append(max(1, min(500, limit)))
    with read() as conn:
        rows = conn.execute(sql, args).fetchall()
        totals = conn.execute(
            "SELECT status, COUNT(*) AS n, COALESCE(SUM(amount_cents),0) AS cents "
            "FROM payments GROUP BY status"
        ).fetchall()
    return {
        "items": [pm__payment_dict(r) for r in rows],
        "totals": {t["status"]: {"count": t["n"], "cents": t["cents"]} for t in totals},
    }


def pm_admin_confirm(payment_id, admin_name, external_ref=None):
    with tx() as conn:
        row = conn.execute("SELECT * FROM payments WHERE id=?", (payment_id,)).fetchone()
        if not row:
            raise pm_PaymentError("Payment not found", 404, "payment_not_found")
        if row["status"] == "paid":
            raise pm_PaymentError("This payment is already confirmed", 409, "already_paid")
        if row["status"] == "void":
            raise pm_PaymentError("This payment was voided", 409, "payment_void")
        now = iso()
        conn.execute(
            "UPDATE payments SET status='paid', paid_at=?, updated_at=?, reviewed_by=?, external_ref=? WHERE id=?",
            (now, now, admin_name, external_ref, payment_id),
        )
        move(conn, row["pin"], int(row["amount_cents"]), "topup",
             counterparty=row["tendered_pin"], ref=payment_id,
             note=f"{row['method']} top-up {row['code'] or ''}".strip())
        audit(conn, admin_name, "payment.confirm", payment_id, None,
              {"amount_cents": row["amount_cents"], "method": row["method"]})
        out = conn.execute("SELECT * FROM payments WHERE id=?", (payment_id,)).fetchone()
    return pm__payment_dict(out)


def pm_admin_void(payment_id, admin_name, reason=None):
    with tx() as conn:
        row = conn.execute("SELECT * FROM payments WHERE id=?", (payment_id,)).fetchone()
        if not row:
            raise pm_PaymentError("Payment not found", 404, "payment_not_found")
        if row["status"] == "paid":
            raise pm_PaymentError("Confirmed payments must be reversed with an adjustment", 409, "already_paid")
        conn.execute(
            "UPDATE payments SET status='void', updated_at=?, reviewed_by=?, note=? WHERE id=?",
            (iso(), admin_name, reason or row["note"], payment_id),
        )
        audit(conn, admin_name, "payment.void", payment_id, None, {"reason": reason})
        out = conn.execute("SELECT * FROM payments WHERE id=?", (payment_id,)).fetchone()
    return pm__payment_dict(out)


import os
