APP_DIR = os.path.dirname(os.path.abspath(__file__))
PUBLIC_DIR = os.path.join(APP_DIR, "public")
COOKIE = os.environ.get("SESSION_COOKIE", "pl_session")
ADMIN_COOKIE = os.environ.get("ADMIN_COOKIE", "pl_admin")
COOKIE_SECURE = os.environ.get("COOKIE_SECURE", "0") == "1"
TRUST_PROXY = os.environ.get("TRUST_PROXY", "1") == "1"
USER_TTL_DAYS = int(os.environ.get("SESSION_TTL_DAYS", "7"))
ADMIN_TTL_HOURS = int(os.environ.get("ADMIN_TTL_HOURS", "12"))

app = FastAPI(title="PinLink API", version="1.0.0", docs_url=None, redoc_url=None)


@app.on_event("startup")
def _startup():
    init_db()
    bl_start_sweeper()


@app.middleware("http")
async def security_headers(request: Request, call_next):
    if request.method in ("POST", "PATCH", "PUT", "DELETE"):
        if request.headers.get("x-pinlink") != "1" and not request.url.path.startswith("/api/health"):
            return JSONResponse({"detail": "missing request signature"}, status_code=400)
    response = await call_next(request)
    response.headers["X-Content-Type-Options"] = "nosniff"
    response.headers["X-Frame-Options"] = "SAMEORIGIN"
    response.headers["Referrer-Policy"] = "same-origin"
    response.headers["Permissions-Policy"] = "camera=(self), microphone=(self), geolocation=()"
    response.headers["Content-Security-Policy"] = (
        "default-src 'self'; img-src 'self' data: blob: https:; media-src 'self' blob:; "
        "style-src 'self' 'unsafe-inline'; script-src 'self'; connect-src 'self'; "
        "font-src 'self' data:; object-src 'none'; base-uri 'none'; frame-ancestors 'self'"
    )
    return response


# ----------------------------------------------------------------------------
# helpers
# ----------------------------------------------------------------------------


def client_ip(request: Request):
    if TRUST_PROXY:
        fwd = request.headers.get("x-forwarded-for")
        if fwd:
            return fwd.split(",")[0].strip()
    return request.client.host if request.client else "unknown"


def _valid_until_iso(months=None):
    """Pins bought or issued carry a 12 month validity window (no refunds)."""
    try:
        m = int(months if months is not None else get_settings().get("pin_valid_months", 12))
    except Exception:
        m = 12
    if m <= 0:
        return None
    return iso(utcnow() + timedelta(days=30 * m))


def account_dict(row):
    if not row:
        return None
    return {
        "pin": row["pin"],
        "name": row["display_name"],
        "handle": row["handle"],
        "role": row["role"],
        "email": row["email"] if "email" in row.keys() else None,
        "bio": row["bio"] if "bio" in row.keys() else None,
        "avatar_seed": row["avatar_seed"],
        "avatar_url": row["avatar_url"] if "avatar_url" in row.keys() else None,
        "call_phone": row["call_phone"] if "call_phone" in row.keys() else None,
        "valid_until": row["valid_until"] if "valid_until" in row.keys() else None,
        "status": row["status"],
        "balance_cents": row["balance_cents"],
        "public_balance": bool(row["public_balance"]),
        "is_master": bool(row["is_master"]) if "is_master" in row.keys() else False,
        "created_at": row["created_at"],
    }


def new_auth_session(kind, subject, request: Request, ttl):
    token = secrets.token_urlsafe(32)
    now = utcnow()
    with tx() as c:
        c.execute(
            "INSERT INTO auth_sessions(token_hash, subject, kind, created_at, expires_at, last_seen, ip, user_agent) "
            "VALUES(?,?,?,?,?,?,?,?)",
            (hash_token(token), subject, kind, iso(now), iso(now + ttl), iso(now), client_ip(request),
             (request.headers.get("user-agent") or "")[:250]),
        )
        c.execute("DELETE FROM auth_sessions WHERE expires_at < ?", (iso(now),))
    return token


def set_cookie(response: Response, name, token, ttl_seconds):
    response.set_cookie(
        name, token, max_age=ttl_seconds, httponly=True,
        samesite="lax", secure=COOKIE_SECURE, path="/",
    )


def current_user(request: Request):
    token = request.cookies.get(COOKIE)
    if not token:
        raise HTTPException(401, "sign in required")
    with read() as c:
        s = c.execute(
            "SELECT * FROM auth_sessions WHERE token_hash=? AND kind='user' AND expires_at > ?",
            (hash_token(token), iso()),
        ).fetchone()
        if not s:
            raise HTTPException(401, "session expired")
        row = c.execute("SELECT * FROM accounts WHERE pin=?", (s["subject"],)).fetchone()
        if not row or row["status"] != "active":
            raise HTTPException(403, "account unavailable")
        c.execute("UPDATE auth_sessions SET last_seen=? WHERE token_hash=?", (iso(), hash_token(token)))
        return row


def optional_user(request: Request):
    try:
        return current_user(request)
    except HTTPException:
        return None


def current_admin(request: Request):
    token = request.cookies.get(ADMIN_COOKIE)
    if not token:
        raise HTTPException(401, "admin sign in required")
    with read() as c:
        s = c.execute(
            "SELECT * FROM auth_sessions WHERE token_hash=? AND kind='admin' AND expires_at > ?",
            (hash_token(token), iso()),
        ).fetchone()
        if not s:
            raise HTTPException(401, "admin session expired")
        a = c.execute("SELECT username, pin FROM admins WHERE username=?", (s["subject"],)).fetchone()
        if not a:
            raise HTTPException(401, "admin not found")
        return {"username": a["username"], "pin": a["pin"]}


def fail(message, status=400, code="error", extra=None):
    payload = {"detail": message, "code": code}
    if extra:
        payload.update(extra)
    raise HTTPException(status, payload)


@app.exception_handler(pm_PaymentError)
def _payment_error(request: Request, exc: pm_PaymentError):
    payload = {"detail": exc.message, "code": exc.code}
    payload.update(exc.extra)
    return JSONResponse(payload, status_code=exc.status)


@app.exception_handler(bl_BillingError)
def _billing_error(request: Request, exc: bl_BillingError):
    payload = {"detail": exc.message, "code": exc.code}
    payload.update(exc.extra)
    return JSONResponse(payload, status_code=exc.status)


