class RegisterBody(BaseModel):
    name: str
    password: str
    pin: Optional[str] = None
    email: Optional[str] = None
    handle: Optional[str] = None


class LoginBody(BaseModel):
    pin: str
    password: str


class AdminLoginBody(BaseModel):
    username: str
    password: str
    pin: str
    secret: str


@app.post("/api/auth/register")
def register(body: RegisterBody, request: Request, response: Response):
    if get_settings().get("allow_self_signup", "1") != "1":
        fail("self signup is closed - ask an agent for a pin", 403, "signup_closed")
    if rate_peek("register:" + client_ip(request)) > 12:
        fail("too many attempts, try later", 429, "rate_limited")
    name = (body.name or "").strip()
    if len(name) < 2:
        fail("please enter your name", 400, "invalid_name")
    if len(body.password or "") < 8:
        fail("password must be at least 8 characters", 400, "weak_password")
    pin = re.sub(r"\D", "", body.pin or "")
    if pin and len(pin) != 11:
        fail("a pin is exactly 11 digits", 400, "invalid_pin")
    if pin and pin.startswith("0"):
        fail("pins cannot start with 0", 400, "invalid_pin")

    with tx() as c:
        if pin and c.execute("SELECT 1 FROM accounts WHERE pin=?", (pin,)).fetchone():
            fail("that pin is already taken", 409, "pin_taken")
        if not pin:
            for _ in range(50):
                pin = generate_pin()
                if not c.execute("SELECT 1 FROM accounts WHERE pin=?", (pin,)).fetchone():
                    break
        base = re.sub(r"[^a-z0-9.]", "", (body.handle or name).lower().replace(" ", "."))[:20] or "member"
        handle = base
        n = 1
        while c.execute("SELECT 1 FROM accounts WHERE handle=?", (handle,)).fetchone():
            n += 1
            handle = f"{base}{n}"
        c.execute(
            "INSERT INTO accounts(pin, display_name, handle, role, password_hash, email, avatar_seed, status, balance_cents, created_at) "
            "VALUES(?,?,?, 'user', ?, ?, ?, 'active', 0, ?)",
            (pin, name, handle, hash_secret(body.password), (body.email or "").strip() or None, base, iso()),
        )
        move(c, pin, 0, "opening_balance", note="account opened")
        rate_hit("register:" + client_ip(request))
        audit(c, pin, "auth.register", pin, client_ip(request), None)
    token = new_auth_session("user", pin, request, timedelta(days=USER_TTL_DAYS))
    set_cookie(response, COOKIE, token, USER_TTL_DAYS * 86400)
    with read() as c:
        row = c.execute("SELECT * FROM accounts WHERE pin=?", (pin,)).fetchone()
    return {"account": account_dict(row), "pin": pin}


@app.post("/api/auth/login")
def login(body: LoginBody, request: Request, response: Response):
    pin = re.sub(r"\D", "", body.pin or "")
    bucket = "login:" + client_ip(request)
    if rate_peek(bucket) >= 12:
        fail("too many failed attempts. wait 15 minutes.", 429, "rate_limited")
    with read() as c:
        row = c.execute("SELECT * FROM accounts WHERE pin=?", (pin,)).fetchone()
        if not row and len(pin) == 4:
            row = c.execute("SELECT * FROM accounts WHERE pin=?", (pin,)).fetchone()
    if not row or not verify_secret(body.password or "", row["password_hash"]):
        rate_hit(bucket)
        fail("pin or password is incorrect", 401, "bad_credentials")
    if row["status"] != "active":
        fail("this pin is suspended", 403, "suspended")
    expires_on = row["valid_until"] if "valid_until" in row.keys() else None
    if expires_on and expires_on < iso():
        fail("this pin expired on %s. ask an agent to top up to keep it active." % expires_on[:10],
             403, "pin_expired")
    with tx() as c:
        c.execute("UPDATE accounts SET last_login_at=? WHERE pin=?", (iso(), row["pin"]))
    token = new_auth_session("user", row["pin"], request, timedelta(days=USER_TTL_DAYS))
    set_cookie(response, COOKIE, token, USER_TTL_DAYS * 86400)
    return {"account": account_dict(row)}


@app.post("/api/auth/logout")
def logout(request: Request, response: Response):
    token = request.cookies.get(COOKIE)
    if token:
        with tx() as c:
            c.execute("DELETE FROM auth_sessions WHERE token_hash=?", (hash_token(token),))
    response.delete_cookie(COOKIE, path="/")
    return {"ok": True}


@app.get("/api/auth/me")
def me(request: Request, user=Depends(current_user)):
    return {"account": account_dict(user), "server_time": iso(), "epoch_ms": int(time.time() * 1000)}


class ProfileBody(BaseModel):
    display_name: Optional[str] = None
    bio: Optional[str] = None
    avatar_url: Optional[str] = None
    call_phone: Optional[str] = None


@app.patch("/api/me")
@app.post("/api/me")
def update_me(body: ProfileBody, user=Depends(current_user)):
    sets, params = [], []
    if body.display_name is not None:
        name = body.display_name.strip()[:40]
        if len(name) < 2:
            fail("that name is too short", 400, "invalid_name")
        sets.append("display_name=?")
        params.append(name)
    if body.bio is not None:
        sets.append("bio=?")
        params.append(body.bio.strip()[:160])
    if body.avatar_url is not None:
        url = body.avatar_url.strip()
        if url and not (url.startswith("data:image/") or url.startswith("https://") or url.startswith("http://")):
            fail("the photo must be an https link or an uploaded image", 400, "invalid_avatar")
        if len(url) > 1200000:
            fail("that image is too large, please use one under 700 KB", 400, "avatar_too_large")
        sets.append("avatar_url=?")
        params.append(url or None)
    if body.call_phone is not None:
        raw = body.call_phone.strip()
        digits = re.sub(r"\D", "", raw)
        if raw and (len(digits) < 8 or len(digits) > 15):
            fail("enter the full phone number with country code", 400, "invalid_phone")
        sets.append("call_phone=?")
        params.append(("+" + digits) if digits else None)
    if not sets:
        return {"account": account_dict(user)}
    with tx() as c:
        params.append(user["pin"])
        c.execute("UPDATE accounts SET " + ", ".join(sets) + " WHERE pin=?", params)
        row = c.execute("SELECT * FROM accounts WHERE pin=?", (user["pin"],)).fetchone()
        audit(c, user["pin"], "profile.update", user["pin"], None, None)
    return {"account": account_dict(row)}


@app.post("/api/admin/login")
def admin_login(body: AdminLoginBody, request: Request, response: Response):
    bucket = "adminlogin:" + client_ip(request)
    if rate_peek(bucket) >= 8:
        fail("too many attempts. wait 15 minutes.", 429, "rate_limited")
    with read() as c:
        a = c.execute("SELECT * FROM admins WHERE username=?", (body.username.strip(),)).fetchone()
    ok = bool(a) and verify_secret(body.password or "", a["password_hash"]) \
        and secrets.compare_digest(str(body.pin or "").strip(), str(a["pin"])) \
        and verify_secret((body.secret or "").strip().lower(), a["secret_hash"])
    if not ok:
        rate_hit(bucket)
        fail("admin credentials are incorrect", 401, "bad_credentials")
    token = new_auth_session("admin", a["username"], request, timedelta(hours=ADMIN_TTL_HOURS))
    set_cookie(response, ADMIN_COOKIE, token, ADMIN_TTL_HOURS * 3600)
    return {"admin": {"username": a["username"]}, "expires_in": ADMIN_TTL_HOURS * 3600}


