    token = request.cookies.get(ADMIN_COOKIE)
    if token:
        with tx() as c:
            c.execute("DELETE FROM auth_sessions WHERE token_hash=?", (hash_token(token),))
    response.delete_cookie(ADMIN_COOKIE, path="/")
    return {"ok": True}


