@app.get("/api/directory/{pin}")
def directory(pin: str, request: Request):
    pin = normalise_pin(pin)
    user = optional_user(request)
    with read() as c:
        row = c.execute("SELECT * FROM accounts WHERE pin=?", (pin,)).fetchone()
        if not row:
            fail("no pin matches that number", 404, "pin_not_found")
        services = [dict(s) for s in c.execute(
            "SELECT id, kind, title, rate_cents_per_min, per_use_cents, min_minutes, active FROM services WHERE agent_pin=? AND active=1 ORDER BY id",
            (pin,)).fetchall()]
        tiers = [dict(t) for t in c.execute(
            "SELECT id, name, price_cents, included_minutes, discount_pct, period_days, perks FROM tiers WHERE agent_pin=? AND active=1 ORDER BY price_cents",
            (pin,)).fetchall()]
        shows = [dict(s) for s in c.execute(
            "SELECT id, title, category, cover_style, description, starts_at, ppv_cents, status FROM live_shows WHERE agent_pin=? ORDER BY starts_at",
            (pin,)).fetchall()]
        subscribers = c.execute("SELECT COUNT(*) AS n FROM subscriptions WHERE agent_pin=? AND status='active'", (pin,)).fetchone()["n"]
        sub = None
        if user:
            sub = c.execute(
                "SELECT s.id, t.name, t.discount_pct, s.ends_at FROM subscriptions s JOIN tiers t ON t.id=s.tier_id "
                "WHERE s.pin=? AND s.agent_pin=? AND s.status='active' AND s.ends_at > ? ORDER BY s.id DESC LIMIT 1",
                (user["pin"], pin, iso())).fetchone()
            sub = dict(sub) if sub else None
        acct = account_dict(row)
        if not acct["public_balance"] and (not user or user["pin"] != pin):
            acct["balance_cents"] = None
        acct.pop("email", None)
    return {"account": acct, "services": services, "tiers": tiers, "shows": shows,
            "subscribers": subscribers, "subscription": sub,
            "is_self": bool(user and user["pin"] == pin), "server_time": iso()}


@app.get("/api/feed")
def feed(request: Request):
    user = optional_user(request)
    with read() as c:
        rows = c.execute(
            "SELECT a.*, (SELECT MIN(rate_cents_per_min) FROM services s WHERE s.agent_pin=a.pin AND s.active=1 AND s.rate_cents_per_min>0) AS min_rate "
            "FROM accounts a WHERE a.role='agent' AND a.is_master=0 AND a.status='active' ORDER BY a.created_at DESC"
        ).fetchall()
        out = []
        for r in rows:
            shows = [dict(s) for s in c.execute(
                "SELECT id, title, category, cover_style, starts_at, ppv_cents, status FROM live_shows WHERE agent_pin=? AND status IN ('live','scheduled') ORDER BY status='live' DESC, starts_at LIMIT 2",
                (r["pin"],)).fetchall()]
            out.append({
                "account": {**account_dict(r), "balance_cents": r["balance_cents"] if r["public_balance"] else None},
                "min_rate_cents": r["min_rate"],
                "shows": shows,
                "subscribed": bool(user and c.execute(
                    "SELECT 1 FROM subscriptions WHERE pin=? AND agent_pin=? AND status='active' AND ends_at > ?",
                    (user["pin"], r["pin"], iso())).fetchone()),
            })
    return {"items": out, "server_time": iso()}


@app.get("/api/dial/recent")
def dial_recent(user=Depends(current_user)):
    with read() as c:
        rows = c.execute(
            "SELECT a.pin, a.display_name, a.handle, a.avatar_seed, MAX(s.id) AS last_id, s.kind, s.started_at "
            "FROM sessions s JOIN accounts a ON a.pin = s.agent_pin WHERE s.caller_pin=? "
            "GROUP BY s.agent_pin ORDER BY last_id DESC LIMIT 8", (user["pin"],)
        ).fetchall()
        threads = c.execute(
            "SELECT a.pin, a.display_name, a.handle, a.avatar_seed, t.last_message_at FROM threads t "
            "JOIN accounts a ON a.pin = CASE WHEN t.a_pin=? THEN t.b_pin ELSE t.a_pin END "
            "WHERE t.a_pin=? OR t.b_pin=? ORDER BY COALESCE(t.last_message_at, t.created_at) DESC LIMIT 8",
            (user["pin"], user["pin"], user["pin"]),
        ).fetchall()
    seen = set()
    out = []
    for r in list(rows) + list(threads):
        if r["pin"] in seen:
            continue
        seen.add(r["pin"])
        out.append({"pin": r["pin"], "name": r["display_name"], "handle": r["handle"], "avatar_seed": r["avatar_seed"]})
    return {"items": out[:8]}


