def wallet_payload(conn, user_row):
    pin = user_row["pin"]
    settings = get_settings()
    minute_value = int(settings.get("minute_value_cents", 1))
    balance = conn.execute("SELECT balance_cents FROM accounts WHERE pin=?", (pin,)).fetchone()["balance_cents"]
    cashable = bl_cashable_cents(conn, pin) if user_row["role"] == "agent" else 0
    recent = [dict(r) for r in conn.execute(
        "SELECT id, ts, kind, amount_cents, minutes, balance_after, counterparty, note FROM ledger WHERE pin=? ORDER BY id DESC LIMIT 12",
        (pin,)).fetchall()]
    return {
        "pin": pin,
        "balance_cents": balance,
        "minutes": int(balance // minute_value) if minute_value else 0,
        "cashable_cents": cashable,
        "cashable_minutes": int(cashable // minute_value) if minute_value else 0,
        "currency": settings.get("currency", "USD"),
        "minute_value_cents": minute_value,
        "grace_seconds": int(settings.get("grace_seconds", 45)),
        "platform_fee_pct": int(settings.get("platform_fee_pct", 0)),
        "role": user_row["role"],
        "recent": recent,
    }


@app.get("/api/wallet")
def wallet(user=Depends(current_user)):
    with read() as c:
        return wallet_payload(c, user)


@app.get("/api/wallet/ledger")
def wallet_ledger(limit: int = 40, offset: int = 0, kind: Optional[str] = None, user=Depends(current_user)):
    limit = max(1, min(200, limit))
    with read() as c:
        if kind:
            rows = c.execute(
                "SELECT * FROM ledger WHERE pin=? AND kind=? ORDER BY id DESC LIMIT ? OFFSET ?",
                (user["pin"], kind, limit, offset)).fetchall()
        else:
            rows = c.execute(
                "SELECT * FROM ledger WHERE pin=? ORDER BY id DESC LIMIT ? OFFSET ?",
                (user["pin"], limit, offset)).fetchall()
        names = {r["pin"]: r["display_name"] for r in c.execute("SELECT pin, display_name FROM accounts").fetchall()}
    items = []
    for r in rows:
        d = dict(r)
        d["counterparty_name"] = names.get(r["counterparty"], r["counterparty"])
        items.append(d)
    return {"items": items, "limit": limit, "offset": offset}


@app.get("/api/wallet/check/{pin}")
def check_pin(pin: str, user=Depends(current_user)):
    pin = normalise_pin(pin)
    with read() as c:
        row = c.execute("SELECT * FROM accounts WHERE pin=?", (pin,)).fetchone()
        if not row:
            return {"exists": False, "pin": pin}
        is_self = row["pin"] == user["pin"] or user["role"] == "admin"
        visible = is_self or bool(row["public_balance"])
        minute_value = int(get_settings().get("minute_value_cents", 1))
        return {
            "exists": True,
            "pin": row["pin"],
            "name": row["display_name"],
            "handle": row["handle"],
            "role": row["role"],
            "avatar_seed": row["avatar_seed"],
            "status": row["status"],
            "balance_visible": visible,
            "balance_cents": row["balance_cents"] if visible else None,
            "minutes": int(row["balance_cents"] // minute_value) if visible and minute_value else None,
        }


