@app.get("/api/threads")
def threads(user=Depends(current_user)):
    with read() as c:
        rows = c.execute(
            "SELECT t.id, t.last_message_at, "
            "CASE WHEN t.a_pin=? THEN t.b_pin ELSE t.a_pin END AS other_pin "
            "FROM threads t WHERE t.a_pin=? OR t.b_pin=? ORDER BY COALESCE(t.last_message_at, t.created_at) DESC",
            (user["pin"], user["pin"], user["pin"]),
        ).fetchall()
        items = []
        for r in rows:
            other = c.execute("SELECT pin, display_name, handle, avatar_seed, role FROM accounts WHERE pin=?",
                              (r["other_pin"],)).fetchone()
            last = c.execute("SELECT body, ts, from_pin FROM messages WHERE thread_id=? ORDER BY id DESC LIMIT 1",
                             (r["id"],)).fetchone()
            if not other:
                continue
            items.append({"id": r["id"], "last_message_at": r["last_message_at"],
                          "other": {"pin": other["pin"], "name": other["display_name"], "handle": other["handle"],
                                    "avatar_seed": other["avatar_seed"], "role": other["role"]},
                          "last": dict(last) if last else None})
    return {"items": items}


@app.get("/api/threads/{pin}")
def thread_detail(pin: str, user=Depends(current_user)):
    pin = normalise_pin(pin)
    a, b = sorted([user["pin"], pin])
    with read() as c:
        other = c.execute("SELECT pin, display_name, handle, avatar_seed, role, avatar_url, call_phone FROM accounts WHERE pin=?", (pin,)).fetchone()
        if not other:
            fail("pin not found", 404, "pin_not_found")
        t = c.execute("SELECT * FROM threads WHERE a_pin=? AND b_pin=?", (a, b)).fetchone()
        msgs = []
        if t:
            msgs = [dict(m) for m in c.execute(
                "SELECT id, from_pin, to_pin, body, ts, charged_cents FROM messages WHERE thread_id=? ORDER BY id",
                (t["id"],)).fetchall()]
        svc = c.execute(
            "SELECT id, rate_cents_per_min, per_use_cents, title FROM services WHERE agent_pin=? AND kind='text' AND active=1 ORDER BY id LIMIT 1",
            (pin,)).fetchone()
    return {"thread_id": t["id"] if t else None,
            "other": {"pin": other["pin"], "name": other["display_name"], "handle": other["handle"],
                      "avatar_seed": other["avatar_seed"], "role": other["role"],
                      "avatar_url": other["avatar_url"], "call_phone": other["call_phone"]},
            "messages": msgs, "pricing": dict(svc) if svc else None,
            "minute_value_cents": int(get_settings().get("minute_value_cents", 1))}


