def _day_bounds(days=7):
    return [iso(utcnow() - timedelta(days=i)) for i in range(days, -1, -1)]


@app.get("/api/admin/stats")
def admin_stats(admin=Depends(current_admin)):
    with read() as c:
        pins = c.execute("SELECT COUNT(*) AS n FROM accounts").fetchone()["n"]
        active = c.execute("SELECT COUNT(*) AS n FROM accounts WHERE status='active'").fetchone()["n"]
        agents = c.execute("SELECT COUNT(*) AS n FROM accounts WHERE role='agent' AND is_master=0").fetchone()["n"]
        total_balance = c.execute("SELECT COALESCE(SUM(balance_cents),0) AS n FROM accounts").fetchone()["n"]
        since = iso(utcnow() - timedelta(hours=24))
        volume = c.execute(
            "SELECT COALESCE(SUM(-amount_cents),0) AS n FROM ledger WHERE amount_cents < 0 AND ts > ? "
            "AND kind IN ('session_charge','message_charge','ticket_purchase','gift_out','subscription')", (since,)).fetchone()["n"]
        live_sessions = c.execute("SELECT COUNT(*) AS n FROM sessions WHERE status='active'").fetchone()["n"]
        vouchers_issued = c.execute("SELECT COUNT(*) AS n FROM vouchers").fetchone()["n"]
        vouchers_redeemed = c.execute("SELECT COUNT(*) AS n FROM vouchers WHERE status='redeemed'").fetchone()["n"]
        pending = c.execute("SELECT COALESCE(SUM(net_cents),0) AS n FROM payouts WHERE status='pending'").fetchone()["n"]
        fees = c.execute("SELECT COALESCE(SUM(amount_cents),0) AS n FROM ledger WHERE kind='platform_fee' AND ts > ?", (since,)).fetchone()["n"]
        top = [dict(r) for r in c.execute(
            "SELECT a.pin, a.display_name, a.avatar_seed, COALESCE(SUM(l.amount_cents),0) AS earned "
            "FROM accounts a LEFT JOIN ledger l ON l.pin=a.pin AND l.kind IN ('session_earning','gift_in','message_earning','ticket_earning','subscription_earning') "
            "AND l.ts > ? WHERE a.role='agent' AND a.is_master=0 GROUP BY a.pin ORDER BY earned DESC LIMIT 5",
            (iso(utcnow() - timedelta(days=7)),)).fetchall()]
        series = []
        for day in _day_bounds(7):
            nxt = iso(parse_iso(day) + timedelta(days=1))
            v = c.execute(
                "SELECT COALESCE(SUM(-amount_cents),0) AS n FROM ledger WHERE amount_cents < 0 AND ts >= ? AND ts < ? "
                "AND kind IN ('session_charge','message_charge','ticket_purchase','gift_out','subscription')", (day, nxt)).fetchone()["n"]
            s = c.execute("SELECT COUNT(*) AS n FROM sessions WHERE started_at >= ? AND started_at < ?", (day, nxt)).fetchone()["n"]
            series.append({"date": day[:10], "volume_cents": v, "sessions": s})
    return {"pins": pins, "active_pins": active, "agents": agents, "total_balance_cents": total_balance,
            "volume_24h_cents": volume, "live_sessions": live_sessions, "vouchers_issued": vouchers_issued,
            "vouchers_redeemed": vouchers_redeemed, "pending_payouts_cents": pending, "fees_24h_cents": fees,
            "top_agents": top, "series": series, "server_time": iso()}


@app.get("/api/admin/pins")
def admin_pins(q: str = "", limit: int = 200, admin=Depends(current_admin)):
    like = f"%{q.strip()}%"
    with read() as c:
        rows = c.execute(
            "SELECT a.*, (SELECT COUNT(*) FROM services s WHERE s.agent_pin=a.pin) AS service_count "
            "FROM accounts a WHERE a.pin LIKE ? OR a.display_name LIKE ? OR a.handle LIKE ? "
            "ORDER BY a.created_at DESC LIMIT ?", (like, like, like, max(1, min(500, limit)))
        ).fetchall()
        out = []
        for r in rows:
            d = account_dict(r)
            d["service_count"] = r["service_count"]
            d["last_login_at"] = r["last_login_at"]
            d["cash_rate_cents"] = r["cash_rate_cents"] if "cash_rate_cents" in r.keys() else 1
            out.append(d)
    return {"items": out}


class GeneratePinsBody(BaseModel):
    count: int = 1
    role: str = "agent"
    prefix: str = ""
    balance_cents: int = 0
    name_prefix: str = "Agent"
    password: Optional[str] = None
    voice_rate_cents: Optional[int] = None
    video_rate_cents: Optional[int] = None
    text_per_message_cents: Optional[int] = None


@app.post("/api/admin/pins")
def admin_generate_pins(body: GeneratePinsBody, request: Request, admin=Depends(current_admin)):
    count = max(1, min(100, body.count))
    role = body.role if body.role in ("user", "agent") else "agent"
    prefix = re.sub(r"\D", "", body.prefix or "")[:9]
    created = []
    with tx() as c:
        for i in range(count):
            pin = generate_pin(prefix=prefix, exists=lambda p: c.execute("SELECT 1 FROM accounts WHERE pin=?", (p,)).fetchone() is not None)
            pwd = body.password or generate_password(10)
            name = f"{body.name_prefix} {i + 1:02d}".strip()
            base = re.sub(r"[^a-z0-9.]", "", name.lower().replace(" ", "."))[:18] or "agent"
            handle = base
            n = 1
            while c.execute("SELECT 1 FROM accounts WHERE handle=?", (handle,)).fetchone():
                n += 1
                handle = f"{base}{n}"
            c.execute(
                "INSERT INTO accounts(pin, display_name, handle, role, password_hash, avatar_seed, status, balance_cents, created_at, valid_until) "
                "VALUES(?,?,?,?,?,?, 'active', 0, ?, ?)",
                (pin, name, handle, role, hash_secret(pwd), base, iso(), _valid_until_iso()),
            )
            if body.balance_cents:
                move(c, pin, int(body.balance_cents), "admin_credit", counterparty=admin["username"],
                     note="issued by admin")
            if role == "agent" and body.voice_rate_cents is not None:
                c.execute(
                    "INSERT INTO services(agent_pin, kind, title, rate_cents_per_min, per_use_cents, created_at) VALUES(?,?,?,?,0,?)",
                    (pin, "voice", "Voice session", int(body.voice_rate_cents), iso()))
            if role == "agent" and body.video_rate_cents is not None:
                c.execute(
                    "INSERT INTO services(agent_pin, kind, title, rate_cents_per_min, per_use_cents, created_at) VALUES(?,?,?,?,0,?)",
                    (pin, "video", "Video session", int(body.video_rate_cents), iso()))
            if role == "agent" and body.text_per_message_cents is not None:
                c.execute(
                    "INSERT INTO services(agent_pin, kind, title, rate_cents_per_min, per_use_cents, created_at) VALUES(?,?,?,?,?,?)",
                    (pin, "text", "Priority texts", 0, int(body.text_per_message_cents), iso()))
            created.append({"pin": pin, "password": pwd, "name": name, "role": role})
        audit(c, admin["username"], "pins.generate", None, client_ip(request), {"count": count, "role": role})
    return {"items": created, "count": len(created)}


class UpdatePinBody(BaseModel):
    status: Optional[str] = None
    role: Optional[str] = None
    display_name: Optional[str] = None
    public_balance: Optional[bool] = None
    cash_rate_cents: Optional[int] = None
    grant_cents: Optional[int] = None
    password: Optional[str] = None
    bio: Optional[str] = None


@app.patch("/api/admin/pins/{pin}")
def admin_update_pin(pin: str, body: UpdatePinBody, request: Request, admin=Depends(current_admin)):
    pin = normalise_pin(pin)
    fields, values = [], []
    if body.status in ("active", "suspended"):
        fields.append("status=?")
        values.append(body.status)
    if body.role in ("user", "agent"):
        fields.append("role=?")
        values.append(body.role)
    if body.display_name:
        fields.append("display_name=?")
        values.append(body.display_name.strip()[:60])
    if body.public_balance is not None:
        fields.append("public_balance=?")
        values.append(1 if body.public_balance else 0)
    if body.cash_rate_cents is not None:
        fields.append("cash_rate_cents=?")
        values.append(max(0, int(body.cash_rate_cents)))
    if body.password:
        if len(body.password) < 8:
            fail("password must be at least 8 characters", 400, "weak_password")
        fields.append("password_hash=?")
        values.append(hash_secret(body.password))
    if body.bio is not None:
        fields.append("bio=?")
        values.append(body.bio[:300])
    with tx() as c:
        if not c.execute("SELECT 1 FROM accounts WHERE pin=?", (pin,)).fetchone():
            fail("pin not found", 404, "pin_not_found")
        if fields:
            c.execute(f"UPDATE accounts SET {', '.join(fields)} WHERE pin=?", (*values, pin))
        if body.grant_cents:
            move(c, pin, int(body.grant_cents), "admin_credit", counterparty=admin["username"], note="admin grant")
        audit(c, admin["username"], "pins.update", pin, client_ip(request), body.model_dump(exclude_none=True))
    return {"ok": True}


class GenerateVouchersBody(BaseModel):
    count: int = 1
    value_cents: int = 0
    minutes: int = 0
    expires_days: Optional[int] = None
    batch: Optional[str] = None
    prefix: str = "PINLINK"


@app.post("/api/admin/vouchers")
def admin_generate_vouchers(body: GenerateVouchersBody, request: Request, admin=Depends(current_admin)):
    if body.value_cents <= 0 and body.minutes <= 0:
        fail("set a dollar value or a minute amount", 400, "invalid_voucher")
    count = max(1, min(500, body.count))
    days = max(1, min(3650, int(body.expires_days or 365)))  # 12 months by default, no refunds
    expires = iso(utcnow() + timedelta(days=days))
    batch = body.batch or f"B{utcnow().strftime('%Y%m%d%H%M')}"
    codes = []
    with tx() as c:
        for _ in range(count):
            for _try in range(50):
                code = generate_voucher_code(re.sub(r"[^A-Z0-9]", "", (body.prefix or "PINLINK").upper())[:10] or "PINLINK")
                if not c.execute("SELECT 1 FROM vouchers WHERE code=?", (code,)).fetchone():
                    break
            c.execute(
                "INSERT INTO vouchers(code, value_cents, minutes, batch, status, created_by, created_at, expires_at) "
                "VALUES(?,?,?,?, 'active', ?, ?, ?)",
                (code, max(0, body.value_cents), max(0, body.minutes), batch, admin["username"], iso(), expires),
            )
            codes.append({"code": code, "value_cents": body.value_cents, "minutes": body.minutes})
        audit(c, admin["username"], "vouchers.generate", batch, client_ip(request),
              {"count": count, "value_cents": body.value_cents, "minutes": body.minutes})
    return {"items": codes, "batch": batch, "count": count}


@app.get("/api/admin/vouchers")
def admin_vouchers(status: Optional[str] = None, q: str = "", limit: int = 300, admin=Depends(current_admin)):
    sql = "SELECT v.*, a.display_name AS redeemed_name FROM vouchers v LEFT JOIN accounts a ON a.pin=v.redeemed_by WHERE 1=1"
    params = []
    if status:
        sql += " AND v.status=?"
        params.append(status)
    if q:
        sql += " AND (v.code LIKE ? OR v.batch LIKE ?)"
        params += [f"%{q}%", f"%{q}%"]
    sql += " ORDER BY v.created_at DESC LIMIT ?"
    params.append(max(1, min(1000, limit)))
    with read() as c:
        rows = [dict(r) for r in c.execute(sql, params).fetchall()]
    return {"items": rows}


