# agent tools: issue pins and vouchers from the agent's own balance
# ----------------------------------------------------------------------------


def _agent_only(user):
    if user["role"] not in ("agent", "admin"):
        fail("sign in with an agent pin to use this", 403, "forbidden")


def _spend(c, pin, amount, kind, note):
    amount = int(amount)
    if amount <= 0:
        return 0
    row = c.execute("SELECT balance_cents FROM accounts WHERE pin=?", (pin,)).fetchone()
    if not row or row["balance_cents"] < amount:
        fail("not enough balance: that costs $%.2f and you have $%.2f"
             % (amount / 100.0, (row["balance_cents"] if row else 0) / 100.0),
             402, "insufficient_funds")
    move(c, pin, -amount, kind, note=note)
    return amount


class AgentPinsBody(BaseModel):
    count: int = 1
    prefix: str = ""
    credit_cents: int = 0
    name_prefix: str = "Guest"
    voice_rate_cents: Optional[int] = None
    video_rate_cents: Optional[int] = None
    text_per_message_cents: Optional[int] = None


@app.post("/api/agent/pins")
def agent_issue_pins(body: AgentPinsBody, request: Request, user=Depends(current_user)):
    _agent_only(user)
    count = max(1, min(50, body.count))
    credit = max(0, int(body.credit_cents))
    total = credit * count
    prefix = re.sub(r"\D", "", body.prefix or "")[:9]
    created = []
    with tx() as c:
        _spend(c, user["pin"], total, "agent_pin_issue", "issued %d pins" % count)
        for i in range(count):
            pin = generate_pin(prefix=prefix, exists=lambda p: c.execute(
                "SELECT 1 FROM accounts WHERE pin=?", (p,)).fetchone() is not None)
            pwd = generate_password(10)
            name = ("%s %02d" % ((body.name_prefix or "Guest").strip(), i + 1))[:40]
            base = re.sub(r"[^a-z0-9.]", "", name.lower().replace(" ", "."))[:18] or "guest"
            handle, n = base, 1
            while c.execute("SELECT 1 FROM accounts WHERE handle=?", (handle,)).fetchone():
                n += 1
                handle = "%s%d" % (base, n)
            c.execute(
                "INSERT INTO accounts(pin, display_name, handle, role, password_hash, avatar_seed, status, balance_cents, created_at, valid_until) "
                "VALUES(?,?,?,'user',?,?, 'active', 0, ?, ?)",
                (pin, name, handle, hash_secret(pwd), base, iso(), _valid_until_iso()))
            if credit:
                move(c, pin, credit, "agent_credit", counterparty=user["pin"], note="issued by agent")
            for kind, rate, per_use, title in (
                ("voice", body.voice_rate_cents, None, "Voice session"),
                ("video", body.video_rate_cents, None, "Video session"),
                ("text", None, body.text_per_message_cents, "Priority texts"),
            ):
                if rate is not None or per_use is not None:
                    c.execute(
                        "INSERT INTO services(agent_pin, kind, title, rate_cents_per_min, per_use_cents, created_at) "
                        "VALUES(?,?,?,?,?,?)",
                        (pin, kind, title, int(rate or 0), int(per_use or 0), iso()))
            created.append({"pin": pin, "password": pwd, "name": name})
        audit(c, user["pin"], "agent.pins.issue", None, client_ip(request),
              {"count": count, "credit_cents": credit})
    return {"items": created, "count": len(created), "charged_cents": total}


class AgentVoucherBody(BaseModel):
    count: int = 1
    value_cents: int = 0
    minutes: int = 0
    expires_days: int = 365


@app.post("/api/agent/vouchers")
def agent_issue_vouchers(body: AgentVoucherBody, request: Request, user=Depends(current_user)):
    _agent_only(user)
    count = max(1, min(200, body.count))
    value, mins = max(0, int(body.value_cents)), max(0, int(body.minutes))
    if not value and not mins:
        fail("set a dollar value or a minute amount", 400, "invalid_voucher")
    total = value * count
    days = max(1, min(3650, int(body.expires_days or 365)))
    expires = iso(utcnow() + timedelta(days=days))
    codes = []
    with tx() as c:
        _spend(c, user["pin"], total, "agent_voucher_issue", "issued %d vouchers" % count)
        for _ in range(count):
            code = generate_voucher_code("PINLINK")
            for _try in range(40):
                if not c.execute("SELECT 1 FROM vouchers WHERE code=?", (code,)).fetchone():
                    break
                code = generate_voucher_code("PINLINK")
            c.execute(
                "INSERT INTO vouchers(code, value_cents, minutes, batch, status, created_by, created_at, expires_at) "
                "VALUES(?,?,?,?, 'active', ?, ?, ?)",
                (code, value, mins, "AGENT-%s" % user["pin"], user["pin"], iso(), expires))
            codes.append({"code": code, "value_cents": value, "minutes": mins})
        audit(c, user["pin"], "agent.vouchers.issue", None, client_ip(request),
              {"count": count, "value_cents": value, "minutes": mins})
    return {"items": codes, "count": len(codes), "charged_cents": total}


