@app.get("/a/{pin}")
def agent_page(pin: str, request: Request):
    pin = re.sub(r"\D", "", pin or "")
    with read() as c:
        acc = c.execute("SELECT * FROM accounts WHERE pin=?", (pin,)).fetchone()
        if not acc:
            raise HTTPException(404, "No agent uses this pin")
        svcs = c.execute("SELECT * FROM services WHERE agent_pin=? AND active=1 ORDER BY id", (pin,)).fetchall()

    if svcs:
        rows = "".join(
            '<div class="svc"><div>%s<small>%s</small></div><div class="price">%s</div></div>' % (
                _esc(s["title"]),
                _esc((s["kind"] or "service").title()),
                ("$%.2f/min" % (s["rate_cents_per_min"] / 100.0)) if s["rate_cents_per_min"]
                else ("$%.2f each" % (s["per_use_cents"] / 100.0)),
            )
            for s in svcs
        )
    else:
        rows = '<div class="svc"><div>No services listed yet<small>Message this pin for availability</small></div><div class="price">-</div></div>'

    digits = pin
    fmt = "%s %s %s %s" % (digits[:1], digits[1:4], digits[4:7], digits[7:]) if len(digits) == 11 else digits
    link = str(request.base_url).rstrip("/") + "/a/" + pin
    import urllib.parse as _up
    name = acc["display_name"] or "PinLink creator"
    initials = (name.strip()[:1] or "P").upper()
    av_url = (acc["avatar_url"] or "") if "avatar_url" in acc.keys() else ""
    if av_url.startswith("http"):
        av_html = '<img class="av" src="%s" alt="%s">' % (_esc(av_url), _esc(name))
    else:
        av_html = '<div class="av">%s</div>' % _esc(initials)
    phone = (acc["call_phone"] or "") if "call_phone" in acc.keys() else ""
    phone_btn = ('<a class="btn s" href="tel:%s">Call on my phone</a>' % _esc(phone)) if phone else ""
    html_out = (AGENT_PAGE
        .replace("__NAME__", _esc(name))
        .replace("__AVATAR__", av_html)
        .replace("__PHONE_BTN__", phone_btn)
        .replace("__HANDLE__", _esc(acc["handle"] or ""))
        .replace("__ROLE__", _esc((acc["role"] or "member").title()))
        .replace("__BIO__", _esc(acc["bio"] or "Available for voice, video and text sessions on PinLink."))
        .replace("__FMT__", _esc(fmt))
        .replace("__SERVICES__", rows)
        .replace("__QDATA__", _esc(_up.quote(link, safe="")))
        .replace("__PIN__", pin))
    return HTMLResponse(html_out)


def _esc(value):
    import html as _html
    return _html.escape(str(value or ""), quote=True)



# ---------------------------------------------------------------------------
# Free 10 minute test pins (48 hour window from first use, one per email / whatsapp / ip)
# ---------------------------------------------------------------------------
TRIAL_MINUTES = int(os.environ.get("TRIAL_MINUTES", "10"))
TRIAL_HOURS = int(os.environ.get("TRIAL_HOURS", "48"))


def _trial_salt():
    return os.environ.get("TRIAL_SALT") or get_settings().get("app_secret") or "pinlink-trial"


def _h(value):
    import hashlib
    v = (value or "").strip().lower()
    return hashlib.sha256((_trial_salt() + v).encode()).hexdigest() if v else None


def _mask_email(v):
    v = (v or "").strip()
    if "@" not in v:
        return v
    a, b = v.split("@", 1)
    return (a[:2] + "***@" + b) if len(a) > 2 else (a[:1] + "***@" + b)


def _mask_wa(v):
    d = re.sub(r"\D", "", v or "")
    return ("***" + d[-4:]) if len(d) >= 4 else "***"


def expire_trials():
    now = iso()
    with tx() as c:
        rows = c.execute("SELECT * FROM trial_pins WHERE status='active' AND expires_at<=?", (now,)).fetchall()
        for r in rows:
            acc = c.execute("SELECT balance_cents FROM accounts WHERE pin=?", (r["pin"],)).fetchone()
            left = min(acc["balance_cents"], r["credit_cents"]) if acc else 0
            if left > 0:
                move(c, r["pin"], -left, "trial_expired", note="free test minutes expired after %dh" % TRIAL_HOURS)
            c.execute("UPDATE trial_pins SET status='expired' WHERE id=?", (r["id"],))
        return len(rows)


class TrialIssueBody(BaseModel):
    email: str
    whatsapp: str
    name: Optional[str] = None


class TrialOverrideBody(BaseModel):
    email: Optional[str] = None
    whatsapp: Optional[str] = None
    name: Optional[str] = None
    minutes: int = 5
    hours: int = 48


def _issue_trial(body, request, *, bypass=False, minutes=None, hours=None, issued_by=None):
    email = (body.email or "").strip()
    wa = re.sub(r"\D", "", body.whatsapp or "")
    if not re.match(r"^[^@\s]+@[^@\s]+\.[A-Za-z]{2,}$", email):
        fail("enter a valid email address", 400, "invalid_email")
    if len(wa) < 7 or len(wa) > 15:
        fail("enter a valid WhatsApp number with country code", 400, "invalid_whatsapp")
    mins = int(minutes or setting_int("trial_minutes", TRIAL_MINUTES))
    hrs = int(hours or setting_int("trial_hours", TRIAL_HOURS))
    if mins < 1 or mins > 600:
        fail("test minutes must be between 1 and 600", 400, "invalid_minutes")
    if hrs < 1 or hrs > 720:
        fail("test window must be between 1 and 720 hours", 400, "invalid_hours")

    ip = client_ip(request)
    eh, wh, ih = _h(email), _h(wa), _h(ip)
    expire_trials()

    if not bypass:
        with read() as c:
            dup = c.execute(
                "SELECT email_hash, wa_hash, ip_hash FROM trial_pins "
                "WHERE email_hash=? OR wa_hash=? OR ip_hash=? LIMIT 1",
                (eh, wh, ih)).fetchone()
        if dup:
            which = "this email" if dup["email_hash"] == eh else (
                "this WhatsApp number" if dup["wa_hash"] == wh else "this device")
            fail("%s already used the free test. Ask an agent for an extra test pin." % which,
                 409, "trial_already_used")

    # a test pin must be able to afford real calls, so the credit is priced at
    # the trial minute rate rather than the house settlement rate
    credit = mins * setting_int("trial_rate_cents", 299)
    now = utcnow()
    name = (body.name or "").strip() or "Trial guest"
    password = generate_password(12)
    with tx() as c:
        pin = None
        for _ in range(50):
            candidate = generate_pin()
            if not c.execute("SELECT 1 FROM accounts WHERE pin=?", (candidate,)).fetchone():
                pin = candidate
                break
        if not pin:
            fail("could not allocate a test pin, try again", 500, "pin_alloc_failed")
        handle = "trial" + pin[-4:]
        n = 1
        while c.execute("SELECT 1 FROM accounts WHERE handle=?", (handle,)).fetchone():
            n += 1
            handle = "trial" + pin[-4:] + str(n)
        c.execute(
            "INSERT INTO accounts(pin, display_name, handle, role, password_hash, email, avatar_seed, status, balance_cents, created_at) "
            "VALUES(?,?,?, 'user', ?, ?, ?, 'active', 0, ?)",
            (pin, name[:40], handle, hash_secret(password), email, handle, iso(now)),
        )
        move(c, pin, 0, "opening_balance", note="test pin opened")
        move(c, pin, credit, "trial_credit", minutes=mins,
             note="free %d min test pin (%dh cap)" % (mins, hrs))
        c.execute(
            "INSERT INTO trial_pins(pin, email_hash, wa_hash, ip_hash, email_masked, wa_masked, minutes, credit_cents, "
            "status, expires_at, issued_by, created_at) VALUES(?,?,?,?,?,?,?,?, 'active', ?,?,?)",
            (pin, eh, wh, ih, _mask_email(email), _mask_wa(wa), mins, credit,
             iso(now + timedelta(hours=hrs)), issued_by, iso(now)),
        )
        audit(c, pin, "trial.issue", pin, ip, {"minutes": mins, "hours": hrs, "by": issued_by})
    return {"pin": pin, "password": password, "minutes": mins, "credit_cents": credit,
            "expires_at": iso(now + timedelta(hours=hrs)), "hours": hrs}


@app.post("/api/trial/issue")
def trial_issue(body: TrialIssueBody, request: Request):
    if rate_peek("trial:" + client_ip(request)) > 6:
        fail("too many test pins from this device, try later", 429, "rate_limited")
    if get_settings().get("trial_enabled", "1") != "1":
        fail("free tests are paused right now", 403, "trial_disabled")
    out = _issue_trial(body, request)
    rate_hit("trial:" + client_ip(request))
    return out


def _staff(request):
    try:
        current_admin(request)
        return "admin"
    except HTTPException:
        pass
    user = optional_user(request)
    if user and user["role"] in ("agent", "admin"):
        return user["pin"]
    fail("admin or agent sign in required", 403, "forbidden")


@app.post("/api/trial/override")
def trial_override(body: TrialOverrideBody, request: Request):
    who = _staff(request)
    if not body.email and not body.whatsapp:
        fail("enter an email or WhatsApp number for the override", 400, "missing_contact")
    out = _issue_trial(body, request, bypass=True, minutes=body.minutes, hours=body.hours, issued_by=who)
    audit_out = dict(out)
    audit_out.pop("password", None)
    return out


@app.get("/api/admin/trials")
def admin_trials(admin=Depends(current_admin)):
    expire_trials()
    with read() as c:
        rows = c.execute(
            "SELECT t.*, a.display_name, a.balance_cents FROM trial_pins t "
            "LEFT JOIN accounts a ON a.pin = t.pin ORDER BY t.id DESC LIMIT 200").fetchall()
    items = [{
        "pin": r["pin"], "name": r["display_name"], "email": r["email_masked"], "whatsapp": r["wa_masked"],
        "minutes": r["minutes"], "status": r["status"], "balance_cents": r["balance_cents"] or 0,
        "expires_at": r["expires_at"], "created_at": r["created_at"], "issued_by": r["issued_by"],
    } for r in rows]
    return {"items": items, "minutes": TRIAL_MINUTES, "hours": TRIAL_HOURS}


