_MEDIA = {
    ".css": "text/css", ".js": "application/javascript", ".svg": "image/svg+xml",
    ".png": "image/png", ".html": "text/html; charset=utf-8",
}


@app.get("/static/{path:path}")
def static_asset(path: str):
    raw = ASSETS.get("/" + path)
    if not raw:
        raise HTTPException(404, "not found")
    ext = os.path.splitext(path)[1].lower()
    return Response(base64.b64decode(raw), media_type=_MEDIA.get(ext, "application/octet-stream"))


